#!/usr/bin/env bash
# Re-vendor gate/ from the source of truth in xchk-app, then regenerate
# MANIFEST.sha256 over every executable surface of the package. Heads are
# packaging, never forks — do not edit gate/ files in this repo.
#
# Release checklist (Tier 1+2):
#   1. ./scripts/sync-gate.sh
#   2. git commit
#   3. git tag -s vX.Y.Z -m "xchk-plugin vX.Y.Z"   # SIGNED tag, always
#   4. git push --follow-tags
#   5. Installs pin the tag: `hermes plugins install minitru/xchk-plugin@vX.Y.Z`;
#      Claude marketplace entries reference the tagged commit SHA. Never main.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
SRC="${XCHK_APP:-/Volumes/2TB-FAST/sean-overflow/src/xchk/xchk-app}/examples/claude-attestation-guardrails"
cp "$SRC/hooks/xchk_hook.py" "$ROOT/gate/xchk_hook.py"
cp "$SRC/xchk_client.py" "$ROOT/gate/xchk_client.py"
python3 - "$ROOT" <<'EOF'
import ast, hashlib, pathlib, sys
root = pathlib.Path(sys.argv[1])
for p in root.glob("gate/*.py"):
    ast.parse(p.read_text())
# Every file whose bytes participate in enforcement or agent-visible behavior.
COVERED = sorted([
    *root.glob("gate/*.py"),
    # cursor/ wires the same gate into Cursor's own hooks.json. It decides
    # WHICH events reach the gate, so its bytes decide coverage as surely as
    # the gate's do — a silently edited installer could drop preToolUse and
    # leave a live plate gating nothing.
    *root.glob("cursor/*.py"),
    root / "hooks/hooks.json",
    root / "mcp/xchk_mcp.py",
    root / "skills/xchk-adopt/SKILL.md",
    root / ".claude-plugin/plugin.json",
    root / "plugin.json",
    root / "mcp.json",
    root / ".mcp.json",
])
lines = ["# xchk-plugin release manifest — regenerated by scripts/sync-gate.sh",
         "# The gate self-hashes against this file and reports the verdict in",
         "# its status ping (self-attested; issuer holds the known-good copy)."]
for p in COVERED:
    lines.append(f"{hashlib.sha256(p.read_bytes()).hexdigest()}  {p.relative_to(root)}")
(root / "MANIFEST.sha256").write_text("\n".join(lines) + "\n")
print(f"gate/ synced; MANIFEST.sha256 covers {len(COVERED)} files")
EOF
